// `CI` is a special variable which is automatically set to true in the CI by Github and is always
// false by default in local. This value is never manually set or changed
export const CI = process.env.CI;

export const BASE_URL = process.env.BASE_URL || "http://localhost:5005";
// The Mantle (skill-mode) agent runs on a second inspect process; only
// `tests/mantle/` point at it (via `test.use({ baseURL })`).
export const MANTLE_BASE_URL = process.env.MANTLE_BASE_URL || "http://localhost:5006";

// Waits that depend on an LLM turn (bot replies, skill activation, memory
// writes). Longer than the suite-wide expect timeout so UI checks still fail fast.
export const LLM_TIMEOUT = 30_000;

console.info("Running inspector e2e tests on", BASE_URL, "(mantle:", MANTLE_BASE_URL + ")");
